import type { ServiceGraph } from '../domain/model';
import { cadEntry } from './openplan3d-projects';

/**
 * Associations between a physically enclosed CAD room and a canonical journey
 * stage. The CAD geometry, editor project and operational simulation are never
 * changed by this service.
 *
 * Room keys use floor ID + sorted boundary wall IDs rather than the transient
 * Date.now() IDs generated by OpenPlan3D's room detection.
 */
export type CadRoomLink = {
  roomKey: string;
  floorId: string;
  roomName: string;
  stageId: string;
  activity: string;
  owner: string;
  resources: string;
  expectedMinutes: number | null;
  capacity: number | null;
  challenge: string;
  updatedAt: string;
};
export type CadRoomLinkState = {
  version: 1;
  serviceId: string;
  maps: Record<string, Record<string, CadRoomLink>>;
};

const clone = <T,>(value: T): T => structuredClone(value);
const boundText = (value: unknown, max: number, label: string) => {
  if (typeof value !== 'string' || value.length > max) throw new Error(label + ' inválido ou muito longo.');
  return value.trim();
};

/** Stable while boundary wall membership stays the same; renames preserve it. */
export function cadRoomKey(floorId: string, wallIds: string[]): string {
  if (!floorId || floorId.length > 180 || !Array.isArray(wallIds) || wallIds.length < 2 || wallIds.length > 200 ||
      wallIds.some(id => typeof id !== 'string' || !id || id.length > 180)) {
    throw new Error('Limite de identificação do ambiente CAD excedido.');
  }
  return encodeURIComponent(floorId) + '::' + wallIds.slice().sort().map(encodeURIComponent).join(',');
}

export function cadRoomLink(graph: ServiceGraph, mapId: string, roomKey: string): CadRoomLink | null {
  const state = graph.service.cadRoomLinks;
  if (!state || state.serviceId !== graph.service.id) return null;
  return state.maps[mapId]?.[roomKey] ?? null;
}

export type CadRoomLinkInput = Pick<CadRoomLink,
  'roomKey' | 'floorId' | 'roomName' | 'stageId' | 'activity' | 'owner' | 'resources' |
  'expectedMinutes' | 'capacity' | 'challenge'>;

export function saveCadRoomLink(
  graph: ServiceGraph, serviceId: string, mapId: string, input: CadRoomLinkInput,
  date = new Date().toISOString(),
): ServiceGraph {
  if (graph.service.id !== serviceId) throw new Error('O serviço mudou. Reabra os ambientes físicos.');
  if (mapId !== 'service-space' && graph.journeys[mapId]?.serviceId !== serviceId) {
    throw new Error('Esta jornada não pertence ao serviço atual.');
  }
  const entry = cadEntry(graph, mapId);
  if (!entry) throw new Error('Salve primeiro a planta CAD antes de vincular uma sala.');
  const floor = entry.project.floors.find(item => item.id === input.floorId);
  if (!floor || !Array.isArray(floor.walls)) throw new Error('Pavimento CAD indisponível.');
  const wallIds = new Set(floor.walls.map(item =>
    item && typeof item === 'object' && 'id' in item && typeof item.id === 'string' ? item.id : '',
  ).filter(Boolean));
  const keyParts = input.roomKey.split('::');
  let parsed: string[] = [];
  try {
    if (keyParts.length === 2) parsed = keyParts[1].split(',').map(decodeURIComponent);
  } catch { /* Reject invalid URIs below. */ }
  if (parsed.length < 2 || parsed.some(id => !wallIds.has(id)) ||
      cadRoomKey(input.floorId, parsed) !== input.roomKey) {
    throw new Error('A sala mudou no desenho. Selecione-a novamente para vincular.');
  }
  const stage = graph.stages[input.stageId];
  const journey = stage ? graph.journeys[stage.journeyId] : undefined;
  if (!stage || !journey || journey.serviceId !== serviceId || !journey.stageIds.includes(stage.id) ||
      !graph.service.journeyIds.includes(journey.id) ||
      (mapId !== 'service-space' && stage.journeyId !== mapId)) {
    throw new Error('Selecione uma etapa válida da jornada deste serviço.');
  }
  const minutes = input.expectedMinutes;
  const capacity = input.capacity;
  if (minutes !== null && (!Number.isFinite(minutes) || minutes < 0 || minutes > 10080)) {
    throw new Error('Tempo estimado fora do intervalo permitido.');
  }
  if (capacity !== null && (!Number.isInteger(capacity) || capacity < 1 || capacity > 100000)) {
    throw new Error('Capacidade fora do intervalo permitido.');
  }
  const previous = graph.service.cadRoomLinks;
  if (previous && previous.serviceId !== serviceId) {
    throw new Error('Os vínculos desta planta pertencem a outro serviço.');
  }
  const roomLinks = previous?.maps[mapId] ?? {};
  if (!roomLinks[input.roomKey] && Object.keys(roomLinks).length >= 250) {
    throw new Error('Limite de 250 ambientes por mapa atingido.');
  }
  const next: CadRoomLink = {
    roomKey: input.roomKey,
    floorId: input.floorId,
    roomName: boundText(input.roomName, 120, 'Nome do ambiente'),
    stageId: stage.id,
    activity: boundText(input.activity, 240, 'Atividade'),
    owner: boundText(input.owner, 120, 'Responsável'),
    resources: boundText(input.resources, 500, 'Recursos'),
    expectedMinutes: minutes,
    capacity,
    challenge: boundText(input.challenge, 1000, 'Observações'),
    updatedAt: date,
  };
  const changed = clone(graph);
  changed.service.cadRoomLinks = {
    version: 1,
    serviceId,
    maps: {
      ...(previous?.maps ?? {}),
      [mapId]: { ...roomLinks, [input.roomKey]: next },
    },
  };
  changed.service.updatedAt = date;
  return changed;
}

export function removeCadRoomLink(
  graph: ServiceGraph, serviceId: string, mapId: string, roomKey: string,
  date = new Date().toISOString(),
): ServiceGraph {
  if (graph.service.id !== serviceId) throw new Error('Serviço diferente do projeto aberto.');
  const previous = graph.service.cadRoomLinks;
  if (!previous || previous.serviceId !== serviceId || !previous.maps[mapId]?.[roomKey]) return graph;
  const changed = clone(graph);
  const mapLinks = { ...previous.maps[mapId] };
  delete mapLinks[roomKey];
  changed.service.cadRoomLinks = {
    ...previous,
    maps: { ...previous.maps, [mapId]: mapLinks },
  };
  changed.service.updatedAt = date;
  return changed;
}
